          "description": "Comma list of daily variables, e.g. temperature_2m_max,precipitation_sum",
          "type": "string"
        },
        "forecast_days": {
          "default": 7,
          "maximum": 16,
          "minimum": 1,
          "type": "integer"
        },
        "hourly": {
          "description": "Comma list of hourly variables",
          "type": "string"
        },
        "latitude": {
          "description": "Latitude in decimal degrees",
          "type": "number"
        },
        "longitude": {
          "description": "Longitude in decimal degrees",
