          "description": "Timezone name or 'auto' to resolve from coordinates",
          "type": "string"
        }
      },
      "required": [
        "latitude",
        "longitude"
      ],
      "type": "object"
    },
    "name": "meteo:get_weather_forecast"
  }
]

