    "description": "Covers all NWS weather alert retrieval and returns alert lists, counts, or single alert records.\nquery: Search alerts with time-range, pagination, and full filter set; use when historical or future alerts are needed.\nactive: Retrieve all currently live alerts with optional filters; use for real-time monitoring without time bounds.\ncount: Return summary counts of active alerts by category; use when totals are needed, not individual records.\nactive_zone: Get live alerts for a single forecast or county zone ID; use when zone is the only filter.\nactive_area: Get live alerts for a state or marine area code; use for state/territory-level scope.\nactive_region: Get live alerts for a marine region code; use when targeting offshore marine regions.\ntypes: List all recognized alert event type names; use to discover valid values for the event filter.\nsingle: Fetch one alert by its unique identifier; use when the alert ID is already known.\n\nAction parameters (\"?\" = optional):\n- query(active?: boolean, start?: string, end?: string, status?: array, message_type?: array, event?: array, code?: array, area?: array, point?: string, region?: array, region_type?: string [land|marine], zone?: array, urgency?: array, severity?: array, certainty?: array, limit?: integer, cursor?: string)\n- active(status?: array, message_type?: array, event?: array, code?: array, area?: array, point?: string, region?: array, region_type?: string [land|marine], zone?: array, urgency?: array, severity?: array, certainty?: array)\n- count()\n- active_zone(zoneId: string)\n- active_area(area: string)\n- active_region(region: string [AL|AT|GL|GM|PA|PI])\n- types()\n- single(id: string)",
    "inputSchema": {
      "properties": {
        "action": {
          "description": "Which operation to perform; see the tool description for each action.",
          "enum": [
            "query",
            "active",
            "count",
            "active_zone",
            "active_area",
            "active_region",
            "types",
            "single"
          ],
          "type": "string"
        },
        "arguments": {
          "description": "Arguments for the chosen action, matching its documented parameters.",
          "type": "object"
        }
      },
      "required": [
        "action",
        "arguments"
      ],
      "type": "object"
    },
    "name": "nws:alerts"
  },
  {
    "description": "Covers NWS Center Weather Service Unit (CWSU) metadata and their Center Weather Advisories (CWAs), returning office details or advisory records.\nmeta: Retrieve contact and location metadata for a CWSU; use when office information is needed, not advisories.\nadvisories: List all CWAs issued by a CWSU; use when browsing the full advisory history without date filtering.\nsingle: Fetch one specific CWA by date and sequence number; use when the exact advisory identifier is known.\n\nAction parameters (\"?\" = optional):\n- meta(cwsuId: string [ZAB|ZAN|ZAU|ZBW|ZDC|ZDV|ZFA|ZFW|…])\n- advisories(cwsuId: string [ZAB|ZAN|ZAU|ZBW|ZDC|ZDV|ZFA|ZFW|…])\n- single(cwsuId: string [ZAB|ZAN|ZAU|ZBW|ZDC|ZDV|ZFA|ZFW|…], date: string, sequence: integer)",
    "inputSchema": {
      "properties": {
        "action": {
          "description": "Which operation to perform; see the tool description for each action.",
          "enum": [
            "meta",
            "advisories",
            "single"
          ],
          "type": "string"
        },
        "arguments": {
          "description": "Arguments for the chosen action, matching its documented parameters.",
          "type": "object"
        }
      },
      "required": [
        "action",
        "arguments"
      ],
      "type": "object"
    },
    "name": "nws:cwsu_api"
  },
  {
    "description": "Search Hugging Face Hub for models, datasets, spaces, or all repo types at once, returning repository metadata and links. Use hub_repo_details instead when you already know a specific repo ID and need full metadata, file structure, or dataset preview.\n\nParameters:\n- query: Free-text search string\n- repo_types: One or more of \"model\", \"dataset\", \"space\"; omit to search all types\n- author: Filter by owner username or organization\n- filters: Tag or attribute filters (e.g. task, library, language)\n- sort: Ranking criterion (e.g. downloads, likes, lastModified)\n- limit: Maximum number of results to return",
    "inputSchema": {
      "$schema": "https://json-schema.org/draft/2020-12/schema",
      "properties": {
        "author": {
          "description": "Organization or user namespace to filter by (e.g. 'google', 'meta-llama', 'huggingface').",
          "type": "string"
        },
        "filters": {
          "description": "Optional hub filter tags. Applied to each selected repo type (e.g. [\"text-generation\"], [\"language:en\"], [\"mcp-server\"]).",
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "limit": {
          "default": 20,
          "description": "Maximum number of results to return per selected repo type",
          "maximum": 100,
          "minimum": 1,
          "type": "number"
        },
        "query": {
          "description": "Search term. Leave blank and specify sort + limit to browse trending or recent repositories.",
          "type": "string"
        },
        "repo_types": {
          "default": [
            "model",
            "dataset"
          ],
          "description": "Repository types to search. Defaults to [\"model\", \"dataset\"]. space uses keyword search via /api/spaces.",
          "items": {
            "enum": [
              "model",
              "dataset",
              "space"
            ],
            "type": "string"
          },
          "maxItems": 3,
          "minItems": 1,
          "type": "array"
        },
        "sort": {
          "description": "Sort order (descending): trendingScore, downloads, likes, createdAt, lastModified",
          "enum": [
            "trendingScore",
            "downloads",
            "likes",
            "createdAt",
            "lastModified"
          ],
          "type": "string"
        }
      },
      "type": "object"
    },
    "name": "hf:hub_repo_search"
  },
  {
    "description": "Covers NWS forecast office metadata and operational content, returning office details, briefings, headlines, or weather stories.\nmeta: Retrieve address, region, and contact details for an office; use for office identification only.\nbriefing: Retrieve the currently active briefing document; use for live operational briefing content.\nbriefing_latest: Download the most recent briefing file; use when the file download of the latest briefing is needed.\nbriefing_by_id: Download a specific past briefing by its ID; use when the briefing identifier is already known.\nheadline: Fetch full content of one headline by its ID; use after discovering the ID via headlines.\nheadlines: List all current headlines for an office; use to browse or discover headline IDs.\nweatherstory: Retrieve active weather narrative stories for an office; use for public-facing story content.\nweatherstory_image: Fetch an image for a specific weather story; use after obtaining image IDs from weatherstory.\n\nAction parameters (\"?\" = optional):\n- meta(officeId: string)\n- briefing(officeId: string)\n- briefing_latest(officeId: string)\n- briefing_by_id(officeId: string, briefingId: string)\n- headline(officeId: string, headlineId: string)\n- headlines(officeId: string)\n- weatherstory(officeId: string)\n- weatherstory_image(officeId: string, imageId: string)",
    "inputSchema": {
      "properties": {
        "action": {
          "description": "Which operation to perform; see the tool description for each action.",
          "enum": [
            "meta",
            "briefing",
            "briefing_latest",
            "briefing_by_id",
            "headline",
            "headlines",
            "weatherstory",
            "weatherstory_image"
          ],
          "type": "string"
        },
        "arguments": {
          "description": "Arguments for the chosen action, matching its documented parameters.",
          "type": "object"
        }
      },
      "required": [
        "action",
        "arguments"
      ],
      "type": "object"
    },
    "name": "nws:office_api"
  },
  {
    "description": "Create, submit, delete, or manage review threads on a GitHub pull request review. Supports creating pending reviews, submitting them, deleting pending reviews, and resolving/unresolving threads.\n\nParameters:\n- owner: Repository owner\n- repo: Repository name\n- pullNumber: Pull request number\n- method: Action — create, submit_pending, delete_pending, resolve_thread, or unresolve_thread\n- event: Review event type for create/submit: APPROVE, REQUEST_CHANGES, or COMMENT\n- body: Review comment body text\n- commitID: Commit SHA the review applies to\n- threadId: Node ID of the review thread (required for resolve_thread / unresolve_thread; e.g., PRRT_kwDOxxx)",
    "inputSchema": {
      "properties": {
        "body": {
          "description": "Review comment text",
          "type": "string"
        },
        "commitID": {
          "description": "SHA of commit to review",
          "type": "string"
        },
        "event": {
          "description": "Review action to perform.",
          "enum": [
            "APPROVE",
            "REQUEST_CHANGES",
            "COMMENT"
          ],
          "type": "string"
        },
        "method": {
          "description": "The write operation to perform on pull request review.",
          "enum": [
            "create",
            "submit_pending",
            "delete_pending",
            "resolve_thread",
            "unresolve_thread"
          ],
          "type": "string"
        },
        "owner": {
          "description": "Repository owner",
          "type": "string",
          "x-mcp-header": "owner"
        },
        "pullNumber": {
          "description": "Pull request number",
          "type": "number"
        },
        "repo": {
          "description": "Repository name",
          "type": "string",
          "x-mcp-header": "repo"
        },
        "threadId": {
          "description": "The node ID of the review thread (e.g., PRRT_kwDOxxx). Required for resolve_thread and unresolve_thread methods. Get thread IDs from pull_request_read with method get_review_comments.",
          "type": "string"
        }
      },
      "required": [
        "method",
        "owner",
        "repo",
        "pullNumber"
      ],
      "type": "object"
    },
    "name": "github:pull_request_review_write"
  },
