            "observations",
            "stations",
            "transmitter"
          ],
          "type": "string"
        },
        "arguments": {
          "description": "Arguments for the chosen action, matching its documented parameters.",
          "type": "object"
        }
      },
      "required": [
        "action",
        "arguments"
      ],
      "type": "object"
